package com.bank.jvm.g1;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// This file contains multiple classes for the runnable demo.
// In a real project each would live in its own file.
public class PaymentEnrichmentSimulator {

    private static final Logger log = Logger.getLogger(PaymentEnrichmentSimulator.class.getName());

    public static void main(String[] args) {
        HeapReporter reporter = new HeapReporter();
        log.info("Bank: National Bank of India — G1 enrichment simulator starting");
        reporter.report("before");

        // A few long-lived profiles survive into Old regions (like cached customers).
        List<CustomerProfile> longLived = new ArrayList<>();
        longLived.add(new CustomerProfile("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        longLived.add(new CustomerProfile("CUR3001", "Priya Sharma", new BigDecimal("250000")));

        // Many short-lived enrichment records churn through Eden and die fast.
        long totalTransfers = 0;
        for (int i = 0; i < 2_000_000; i++) {
            EnrichmentRecord rec = new EnrichmentRecord("TXN-" + i, longLived.get(i % 2));
            totalTransfers += rec.scoreRisk(); // use it so JIT cannot drop the allocation
            if (i % 500_000 == 0) {
                log.info(() -> "Processed batch, heap sampled");
                reporter.report("during");
            }
        }

        log.info(() -> "Total enrichment score across " + 2_000_000 + " records = " + totalTransfers);
        reporter.report("after");
        log.info("G1 kept short-lived records in Eden; profiles stayed in Old regions");
    }
}

// ─── Would be in CustomerProfile.java in a real project ───
class CustomerProfile {
    private final String accountId;
    private final String holderName;
    private final BigDecimal balance;
    private final byte[] profileBlob = new byte[4096]; // simulates a heavy cached profile

    CustomerProfile(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in EnrichmentRecord.java in a real project ───
class EnrichmentRecord {
    private final String txnId;
    private final CustomerProfile profile;
    private final int[] features = new int[16]; // small, short-lived payload

    EnrichmentRecord(String txnId, CustomerProfile profile) {
        this.txnId = txnId;
        this.profile = profile;
    }
    int scoreRisk() {
        int score = txnId.length() + profile.getHolderName().length();
        for (int f : features) score += f;
        return score & 0x7;
    }
}
